  function summaryFor(title, sectionTitle, module) {
    const lower = title.toLowerCase();
    const normalize = value => value.toLowerCase().replace(/[^a-z0-9]+/g, " ").trim();
    const known = Object.entries(knownSummary).find(([key]) => normalize(key) === normalize(title));
    if (known) return known[1];
    const rule = summaryRules.find(([pattern]) => pattern.test(lower));
    if (rule) return rule[1];
    if (/exercise\s*#?\d*/i.test(title)) return `This is a practice item for ${sectionTitle}. Apply the relevant concept to a small example, predict the result before running it, and test one edge case.`;
    if (/quiz\s*\d*/i.test(title)) return `This quiz checks understanding of ${sectionTitle}. Explain why each answer is correct and revisit the concept behind any missed question.`;
    if (/a note on/i.test(title)) return `This note gives context for the next ${sectionTitle} activity. Check its assumptions and instructions before beginning the practical work.`;
    if (/practical task|assignment|case study/i.test(title)) return `This practical task applies ${sectionTitle} to a realistic problem. Define the inputs and expected output, make the workflow reproducible, and explain the result and its limitations.`;
    if (/introduction|welcome|getting started|course materials|course prerequisites|first steps/i.test(title)) return `This lesson introduces ${sectionTitle} in the ${module} module, explains the learning materials and prerequisites, and establishes the vocabulary used in later lessons.`;
    if (/setting up|environment|installing/i.test(title)) return `This lesson prepares a working environment for ${sectionTitle}. Confirm the interpreter, packages, configuration, and kernel before running later examples.`;
    if (/part i|part ii|part 1|part 2/i.test(title)) return `This lesson develops the ${sectionTitle} workflow in stages. Follow the demonstrated step, inspect intermediate results, and connect it to the preceding part.`;
    return `${title} is a focused concept in ${sectionTitle} (${module}). Understand its inputs and expected result, trace one example, and check the relevant failure case before applying it.`;
  }

